plugins.runCode:
const prompt = String(args.prompt || '').trim();
if (!prompt) throw new Error('需要 prompt');
const isVideo = kind === 'video' || kind === 'videoEdit';
const isFastImg = /fast|speed/i.test(String(args.model || args.engine || ''));
const mapRatio = (ratio, size, forVideo) => {
  const s = String(ratio || '').trim();
  const allowed = forVideo ? ['2:3','3:2','1:1','9:16','16:9'] : ['2:3','3:2','4:3','1:1','9:16','16:9','21:9','5:2'];
  if (/auto|自动/i.test(s)) return '自动模式';
  if (allowed.includes(s)) return s;
  const m = /^(\d+)\s*[xX×:]\s*(\d+)$/.exec(String(size || s));
  if (!m) return '';
  const r = +m[1] / +m[2];
  return r >= 2.3 && allowed.includes('5:2') ? '5:2' : r >= 2.0 && allowed.includes('21:9') ? '21:9' : r >= 1.65 ? '16:9' : r >= 1.42 ? '3:2' : r >= 1.2 && allowed.includes('4:3') ? '4:3' : r >= 0.85 ? '1:1' : r >= 0.62 ? '2:3' : '9:16';
};
const ratioTarget = mapRatio(args.ratio, args.size, isVideo);
const resTarget = isVideo && args.resolution ? (/1080/.test(String(args.resolution)) ? '1080p' : /720/.test(String(args.resolution)) ? '720p' : '480p') : '';
const durNum = isVideo && args.duration ? (+args.duration >= 13 ? '15' : +args.duration >= 8 ? '10' : '6') : '';
const audioTarget = isVideo && args.audio !== undefined ? !!args.audio : null;
const countTarget = !isVideo ? (args.count ? (/auto|自动/i.test(String(args.count)) ? '自动模式' : '×' + String(args.count).replace(/[^\d]/g, '')) : '×2') : '';
const refImages = [].concat(args.images || args.image || []).filter(Boolean);

return tools.openTab('https://grok.com/imagine', async tabId => {
  const [domBefore, assetBefore] = await Promise.all([
    tools.runPage(tabId, `(() => {
      const fp = s => s ? s.slice(0, 160) + '#' + s.length : '';
      return {
        imgs: [...document.querySelectorAll('img')].map(i => fp(i.currentSrc || i.src)).filter(Boolean),
        vids: [...document.querySelectorAll('video,video source')].map(v => v.currentSrc || v.src || '').filter(Boolean),
      };
    })()`, 10000, 'MAIN'),
    isVideo ? tools.fetchInTab(tabId, '/rest/assets?pageSize=8&orderBy=ORDER_BY_CREATE_TIME&sortDirection=SORT_DIRECTION_DESCENDING&source=SOURCE_ANY&isLatest=true&includeImagineFiles=true').catch(() => null) : null,
  ]);
  const oldIds = (assetBefore?.json?.assets || []).map(x => x.assetId);

  await tools.runPage(tabId, `(async (isVideo, isFastImg, audioTarget) => {
    const sleep = ms => new Promise(r => setTimeout(r, ms));
    const vis = e => { const r = e.getBoundingClientRect(); return r.width > 1 && r.height > 1 && getComputedStyle(e).visibility !== 'hidden'; };
    const modeBtn = document.querySelector(isVideo ? 'button[aria-label="视频"],button[aria-label="Video"]' : 'button[aria-label="图片"],button[aria-label="Image"]');
    if (modeBtn && modeBtn.getAttribute('aria-pressed') !== 'true') { modeBtn.click(); await sleep(350); }
    if (isVideo && audioTarget !== null) {
      const ab = document.querySelector('button[aria-label="视频音频"],button[aria-label*="Audio"]');
      if (ab && (ab.getAttribute('aria-pressed') === 'true') !== audioTarget) { ab.click(); await sleep(200); }
    } else if (!isVideo) {
      const want = isFastImg ? '速度' : '质量';
      const eb = [...document.querySelectorAll('button')].find(b => vis(b) && (b.innerText || '').trim().startsWith(want));
      if (eb && eb.getAttribute('aria-pressed') !== 'true') { eb.click(); await sleep(220); }
    }
  })(${JSON.stringify(isVideo)}, ${JSON.stringify(isFastImg)}, ${JSON.stringify(audioTarget)})`, 12000, 'MAIN');

  if (isVideo) {
    if (resTarget) await tools.pickMenu(tabId, 'button[aria-label="视频分辨率"]', resTarget);
    if (durNum) await tools.pickMenu(tabId, 'button[aria-label="视频时长"]', durNum + 's');
    if (ratioTarget) await tools.pickMenu(tabId, 'button[aria-label="宽高比"]', ratioTarget);
  } else {
    if (countTarget) await tools.pickMenu(tabId, 'button[aria-label="图像数量"]', countTarget);
    if (ratioTarget) await tools.pickMenu(tabId, 'button[aria-label="宽高比"]', ratioTarget);
  }

  if (refImages.length) {
    const pasted = await tools.pasteImages(tabId, refImages, '.ProseMirror,[role="textbox"],[contenteditable="true"]', 'button[aria-label="Remove image"],button[aria-label*="移除"],form img[src^="blob:"]');
    if (!pasted) throw new Error('Grok 参考图上传失败，未检测到已附加图片预览');
    await tools.sleep(1000);
  }
  await tools.fillEditor(tabId, prompt, { selector: '.ProseMirror,[role="textbox"],[contenteditable="true"]', submit: true });

  const oldI = domBefore?.imgs || [], oldV = domBefore?.vids || [];
  const t0 = Date.now(), maxMs = isVideo ? 120000 : 100000;
  let picked = null, firstReadyAt = 0, lastLen = 0, stable = 0, seenVidAt = 0, lastVidUrl = '';
  for (let step = 0; Date.now() - t0 < maxMs; step++) {
    if (args.signal?.aborted) throw new Error('已取消');
    await tools.sleep(isVideo ? 1800 : 1200);
    if (isVideo) {
      const st = await tools.runPage(tabId, `((oldVids) => {
        const oldSet = new Set(oldVids || []);
        const idx = location.href.indexOf('/imagine/post/');
        const postId = idx >= 0 ? location.href.slice(idx + 14).split(/[/?#]/)[0] : '';
        const vids = [...new Set([...document.querySelectorAll('video,video source')].map(v => v.currentSrc || v.src || '').filter(u => u && !oldSet.has(u) && (u.startsWith('http') || u.startsWith('blob:') || u.startsWith('data:'))))];
        return { postId, vids };
      })(${JSON.stringify(oldV)})`, 10000, 'MAIN').catch(() => null);
      if (!st) continue;
      const exact = st.postId && st.vids.find(u => u.includes(st.postId));
      if (exact) { picked = { type: 'video', url: exact }; break; }
      let assetUrl = '';
      if (step % 2 === 1 && st.postId) {
        const ar = await tools.fetchInTab(tabId, '/rest/assets?pageSize=8&orderBy=ORDER_BY_CREATE_TIME&sortDirection=SORT_DIRECTION_DESCENDING&source=SOURCE_ANY&isLatest=true&includeImagineFiles=true').catch(() => null);
        const newVids = (ar?.json?.assets || []).filter(x => x.mimeType === 'video/mp4' && !oldIds.includes(x.assetId));
        const hit = newVids.find(x => x.assetId === st.postId) || (refImages.length && newVids.length === 1 && Date.now() - t0 > 30000 ? newVids[0] : null);
        if (hit?.key) assetUrl = 'https://assets.grok.com/' + hit.key;
      }
      if (assetUrl) { picked = { type: 'video', url: assetUrl }; break; }
      if (st.vids.length) {
        if (!seenVidAt) { seenVidAt = Date.now(); lastVidUrl = st.vids[0]; }
        if (Date.now() - seenVidAt >= 4000) { picked = { type: 'video', url: st.vids[0] || lastVidUrl }; break; }
      }
      continue;
    }
    const snap = await tools.runPage(tabId, `((oldImgs) => {
      const fp = s => s ? s.slice(0, 160) + '#' + s.length : '';
      const oldSet = new Set(oldImgs || []);
      const list = [...document.querySelectorAll('img')].map((i, idx) => {
        const u = i.currentSrc || i.src || '', alt = (i.alt || '').trim();
        const ok = !!(u && !oldSet.has(fp(u)) && i.complete && Math.max(i.naturalWidth, i.naturalHeight) >= 512 && alt !== '生成的图像' && !alt.toLowerCase().startsWith('generating') && (u.startsWith('http') || u.startsWith('blob:') || u.startsWith('data:image/')) && !/avatar|icon|logo|cookielaw|profile-picture/i.test(u));
        return ok ? { idx, isData: u.startsWith('data:'), url: u.startsWith('data:') ? '' : u, w: i.naturalWidth, h: i.naturalHeight, len: u.length } : null;
      }).filter(Boolean);
      const hi = list.find(x => !x.isData || x.len >= 280000);
      const pick = hi || list.sort((a, b) => (b.w * b.h) - (a.w * a.h) || b.len - a.len)[0];
      return pick ? Object.assign({ type: 'image' }, pick) : null;
    })(${JSON.stringify(oldI)})`, 10000, 'MAIN').catch(() => null);
    if (!snap) continue;
    picked = snap;
    if (!firstReadyAt) firstReadyAt = Date.now();
    if (snap.len === lastLen) stable++; else { stable = 0; lastLen = snap.len; }
    if (((!snap.isData || snap.len >= 280000) && stable >= 1) || (snap.isData && snap.len < 280000 ? (stable >= 14 || Date.now() - firstReadyAt >= 26000) : (stable >= 3 || Date.now() - firstReadyAt >= 12000))) break;
  }
  if (!picked) throw new Error('等待 Grok Imagine 生成超时，未检测到新媒体');
  if (picked.type === 'image' && picked.isData) {
    const src = await tools.runPage(tabId, `(() => { const i = document.querySelectorAll('img')[${picked.idx}]; return i ? (i.currentSrc || i.src || '') : ''; })()`, 20000, 'MAIN');
    const m = /^data:([^;,]+);base64,(.+)$/.exec(src || '');
    if (m) return { mimeType: m[1], data: m[2] };
    throw new Error('提取生成图 dataUrl 失败');
  }
  return picked.url.startsWith('http')
    ? tools.fetchMedia(picked.url, isVideo ? 'video/mp4' : 'image/jpeg').catch(() => tools.blobFromTab(tabId, picked.url, isVideo ? 'video/mp4' : 'image/jpeg'))
    : tools.blobFromTab(tabId, picked.url, isVideo ? 'video/mp4' : 'image/jpeg');
}, { readyExpr: `document.querySelector('button[aria-label="图片"],button[aria-label="视频"],button[aria-label="Image"]')`, signal: args.signal, timeout: 40000, world: 'MAIN' });

plugins.chatCode:
const msgs = Array.isArray(args.messages) ? args.messages : [];
const sys = msgs.filter(m => m.role === 'system').map(m => tools.textOf(m.content)).filter(Boolean).join('\n');
const hist = msgs.filter(m => m.role !== 'system');
const last = hist[hist.length - 1];
const prompt = (sys ? `[System]\n${sys}\n\n` : '') + (hist.length > 1
  ? hist.map(m => `${m.role === 'assistant' ? 'Assistant' : 'User'}: ${tools.textOf(m.content)}`).join('\n\n')
  : tools.textOf(last?.content || args.prompt || ''));
if (!prompt.trim()) throw new Error('对话内容为空');
const imgs = Array.isArray(last?.content) ? last.content.filter(p => p && p.type === 'image' && (p.data || p.url)) : [];
const m = String(args.model || '').toLowerCase();
const targetMode = /heavy|420/.test(m) ? 'Heavy' : /build/.test(m) ? 'Build' : /expert|grok-4(?!-auto)/.test(m) ? 'Expert' : /fast|grok-3/.test(m) ? 'Fast' : 'Auto';
const usePrivate = args.private !== false;

return tools.openTab('https://grok.com/', async tabId => {
  await tools.runPage(tabId, `(async (priv) => {
    const txt = document.body?.innerText || '';
    const pb = document.querySelector('button[aria-label*="私密"],button[aria-label*="Private"]');
    const isPriv = txt.includes('此聊天不会出现在你的历史记录中') || txt.includes("won't appear in your history")
      || !!(pb && (pb.getAttribute('aria-pressed') === 'true' || /退出|离开|Exit|Leave/i.test(pb.getAttribute('aria-label') || '')));
    if (isPriv !== priv && pb) { pb.click(); await new Promise(r => setTimeout(r, 320)); }
  })(${JSON.stringify(usePrivate)})`, 10000, 'MAIN');
  await tools.pickMenu(tabId, '#model-select-trigger,button[aria-label^="型号:"],button[aria-label^="Model:"]', targetMode);
  if (imgs.length) { await tools.pasteImages(tabId, imgs, '.ProseMirror,[role="textbox"],[contenteditable="true"]'); await tools.sleep(900); }
  await tools.fillEditor(tabId, prompt, { selector: '.ProseMirror,[role="textbox"],[contenteditable="true"]', submit: true });

  const content = await tools.runPage(tabId, `(async () => {
    const sleep = ms => new Promise(r => setTimeout(r, ms));
    let prev = '', stable = 0, t0 = Date.now();
    while (Date.now() - t0 < 150000) {
      await sleep(600);
      const stopBtn = document.querySelector('button[aria-label*="停止"],button[aria-label*="Stop"]');
      const mds = [...document.querySelectorAll('.response-content-markdown')].filter(n => !n.closest('form') && !n.closest('aside'));
      const last = mds.length ? (mds[mds.length - 1].innerText || '').trim() : '';
      const done = (document.body.innerText || '').includes('Grok 已完成回复') || (document.body.innerText || '').includes('Grok finished');
      if (last && !stopBtn) {
        if (done && last === prev) return last;
        if (last === prev) { if (++stable >= 3) return last; } else { stable = 0; prev = last; }
      } else { stable = 0; if (last) prev = last; }
    }
    return prev;
  })()`, 160000, 'MAIN');
  if (!content) throw new Error('未获取到 Grok 网页回复，请确认已登录且未触发配额限制');
  return { content, usage: null, stop: 'stop', toolCalls: null };
}, { readyExpr: `document.querySelector('#model-select-trigger,button[aria-label^="型号:"],button[aria-label^="Model:"]') && document.querySelector('.ProseMirror,[role="textbox"]')`, signal: args.signal, timeout: 25000, world: 'MAIN' });

plugins.observeCode:
const page = String(args.page || 'imagine').toLowerCase();
const url = page === 'chat' ? 'https://grok.com/' : 'https://grok.com/imagine';
const readyExpr = page === 'chat'
  ? `document.querySelector('#model-select-trigger,button[aria-label^="型号:"],button[aria-label^="Model:"]') && document.querySelector('.ProseMirror,[role="textbox"]')`
  : `document.querySelector('button[aria-label="图片"],button[aria-label="视频"],button[aria-label="Image"]')`;
return tools.openTab(url, async tabId => {
  await tools.sleep(350);
  const [snap, sub, fast, expert] = await Promise.all([
    tools.observeTab(tabId, !!args.detail),
    tools.fetchInTab(tabId, '/rest/subscriptions').catch(() => null),
    tools.fetchInTab(tabId, '/rest/rate-limits', { method: 'POST', body: { modelName: 'grok-3', requestKind: 'DEFAULT' } }).catch(() => null),
    tools.fetchInTab(tabId, '/rest/rate-limits', { method: 'POST', body: { modelName: 'grok-4', requestKind: 'DEFAULT' } }).catch(() => null),
  ]);
  return Object.assign(snap || {}, {
    subscription: sub?.json?.subscriptions?.[0]?.tier || 'unknown',
    quota: { fast: fast?.json || null, expert: expert?.json || null },
  });
}, { readyExpr, timeout: 25000, world: 'MAIN' });

plugins.actionCode:
const act = String(args.action || kind || 'observe');
const a = Object.assign({}, args, args.args || {});
const normRatio = (ratio, size, forVideo) => {
  const s = String(ratio || '').trim();
  const allowed = forVideo ? ['2:3','3:2','1:1','9:16','16:9'] : ['2:3','3:2','4:3','1:1','9:16','16:9','21:9','5:2'];
  if (/auto|自动/i.test(s)) return '自动模式';
  if (allowed.includes(s)) return s;
  const m = /^(\d+)\s*[xX×:]\s*(\d+)$/.exec(String(size || s));
  if (!m) return '';
  const r = +m[1] / +m[2];
  return r >= 2.3 && allowed.includes('5:2') ? '5:2' : r >= 2.0 && allowed.includes('21:9') ? '21:9' : r >= 1.65 ? '16:9' : r >= 1.42 ? '3:2' : r >= 1.2 && allowed.includes('4:3') ? '4:3' : r >= 0.85 ? '1:1' : r >= 0.62 ? '2:3' : '9:16';
};

if (act === 'quota' || act === 'limits') {
  const map = { auto: 'grok-4-auto', fast: 'grok-3', expert: 'grok-4', build: 'build', heavy: 'grok-420' };
  return tools.openTab('https://grok.com/', async tabId => {
    const [sub, ...lims] = await Promise.all([
      tools.fetchInTab(tabId, '/rest/subscriptions').catch(() => null),
      ...Object.entries(map).map(([mode, bucket]) =>
        tools.fetchInTab(tabId, '/rest/rate-limits', { method: 'POST', body: { modelName: bucket, requestKind: 'DEFAULT' } })
          .then(r => [mode, r?.json ? { bucket, remaining: r.json.remainingQueries, total: r.json.totalQueries, windowHours: r.json.windowSizeSeconds ? +(r.json.windowSizeSeconds / 3600).toFixed(2) : null } : { bucket, status: r?.status }])
          .catch(e => [mode, { bucket, error: e.message }])
      ),
    ]);
    return { subscription: sub?.json?.subscriptions?.[0]?.tier || 'unknown', modes: Object.fromEntries(lims) };
  }, { readyExpr: `document.readyState !== 'loading'`, timeout: 20000, world: 'MAIN' });
}

if (act === 'library' || act === 'assets') {
  const limit = Math.max(1, Math.min(50, Number(a.limit) || 12));
  const mimeFilter = String(a.type || a.mime || '').toLowerCase();
  const r = await tools.openTab('https://grok.com/', tabId =>
    tools.fetchInTab(tabId, '/rest/assets?pageSize=' + limit + '&orderBy=ORDER_BY_CREATE_TIME&sortDirection=SORT_DIRECTION_DESCENDING&source=SOURCE_ANY&isLatest=true&includeImagineFiles=true'),
    { readyExpr: `document.readyState !== 'loading'`, timeout: 20000, world: 'MAIN' });
  if (!r?.ok || !r.json) throw new Error('拉取照片库失败: HTTP ' + (r?.status || '?'));
  const list = (r.json.assets || []).map(x => ({
    id: x.assetId, mimeType: x.mimeType, name: x.name, sizeBytes: x.sizeBytes, createTime: x.createTime,
    url: x.key ? 'https://assets.grok.com/' + x.key : '',
  })).filter(x => !mimeFilter || (x.mimeType || '').toLowerCase().includes(mimeFilter));
  if (a.download) {
    const ids = Array.isArray(a.assetIds) ? a.assetIds : (a.assetId ? [a.assetId] : null);
    const pick = ids ? ids.map(id => list.find(x => x.id === id)).filter(Boolean) : list.slice(0, Math.min(6, Number(a.downloadCount) || 1));
    const files = await Promise.all(pick.map(async x => Object.assign({ id: x.id, name: x.name, sizeBytes: x.sizeBytes, url: x.url }, await tools.fetchMedia(x.url, x.mimeType || 'application/octet-stream'))));
    return { total: list.length, files };
  }
  return { total: list.length, assets: list };
}

if (act === 'conversations' || act === 'history') {
  const limit = Math.max(1, Math.min(50, Number(a.limit) || 15));
  const r = await tools.openTab('https://grok.com/', tabId =>
    tools.fetchInTab(tabId, '/rest/app-chat/conversations?pageSize=' + limit),
    { readyExpr: `document.readyState !== 'loading'`, timeout: 20000, world: 'MAIN' });
  if (!r?.ok || !r.json) throw new Error('拉取会话历史失败: HTTP ' + (r?.status || '?'));
  return (r.json.conversations || []).map(c => ({ id: c.conversationId, title: c.title, starred: !!c.starred, createTime: c.createTime, modifyTime: c.modifyTime, url: 'https://grok.com/c/' + c.conversationId }));
}

if (act === 'observe') return ctx.call('plugin.web.observe', { id: 'grok', page: a.page || 'imagine', detail: !!a.detail });

if (act === 'chat') {
  const modeMap = { auto: 'grok-4.7-auto', fast: 'grok-4.7-fast', expert: 'grok-4.7-expert', build: 'grok-4.7-build', heavy: 'grok-4.7-heavy' };
  const model = a.model || modeMap[String(a.mode || 'fast').toLowerCase()] || 'grok-4.7-fast';
  const msgs = a.messages || [{ role: 'user', content: a.images || a.image
    ? [{ type: 'text', text: String(a.prompt || a.text || '') }, ...[].concat(a.images || a.image).map(im => typeof im === 'string' ? { type: 'image', url: im } : Object.assign({ type: 'image' }, im))]
    : String(a.prompt || a.text || '') }];
  return ctx.call('ai.chat', { provider: 'Grok (网页)', model, messages: msgs, private: a.private });
}

if (act === 'image' || act === 'imageEdit') {
  const prompt = String(a.prompt || '').trim();
  if (!prompt) throw new Error('image 需要 prompt');
  const isAuto = /auto|自动/i.test(String(a.count || ''));
  const want = isAuto ? 2 : Math.max(1, Math.min(24, parseInt(String(a.count || '1').replace(/[^\d]/g, ''), 10) || 1));
  if (want === 1 && !a.returnAll && !isAuto) {
    return ctx.call(act === 'imageEdit' || a.image || a.images ? 'ai.imageEdit' : 'ai.image', {
      provider: 'Grok (网页)', model: String(a.engine || '').toLowerCase() === 'speed' ? 'grok-imagine-image-fast' : (a.model || 'grok-imagine-image'),
      prompt, image: a.image, images: a.images, size: a.size, ratio: a.ratio, count: a.count || 2, engine: a.engine,
    });
  }
  const isFast = /fast|speed/i.test(String(a.model || a.engine || ''));
  const ratioTarget = normRatio(a.ratio, a.size, false);
  const refImages = [].concat(a.images || a.image || []).filter(Boolean);

  const runBatch = async (batchWant) => {
    const tier = isAuto ? '自动模式' : (batchWant <= 2 ? '×2' : batchWant <= 4 ? '×4' : batchWant <= 8 ? '×8' : '×12');
    return tools.openTab('https://grok.com/imagine', async tabId => {
      const oldImgs = await tools.runPage(tabId, `(() => { const fp = s => s ? s.slice(0, 160) + '#' + s.length : ''; return [...document.querySelectorAll('img')].map(i => fp(i.currentSrc || i.src)).filter(Boolean); })()`, 10000, 'MAIN');
      await tools.runPage(tabId, `(async (isFast) => {
        const sleep = ms => new Promise(r => setTimeout(r, ms));
        const vis = e => { const r = e.getBoundingClientRect(); return r.width > 1 && r.height > 1 && getComputedStyle(e).visibility !== 'hidden'; };
        const mb = document.querySelector('button[aria-label="图片"],button[aria-label="Image"]');
        if (mb && mb.getAttribute('aria-pressed') !== 'true') { mb.click(); await sleep(340); }
        const eb = [...document.querySelectorAll('button')].find(b => vis(b) && (b.innerText || '').trim().startsWith(isFast ? '速度' : '质量'));
        if (eb && eb.getAttribute('aria-pressed') !== 'true') { eb.click(); await sleep(220); }
      })(${JSON.stringify(isFast)})`, 12000, 'MAIN');
      await tools.pickMenu(tabId, 'button[aria-label="图像数量"]', tier);
      if (ratioTarget) await tools.pickMenu(tabId, 'button[aria-label="宽高比"]', ratioTarget);
      if (refImages.length) { const pasted = await tools.pasteImages(tabId, refImages, '.ProseMirror,[role="textbox"],[contenteditable="true"]', 'button[aria-label="Remove image"],button[aria-label*="移除"],form img[src^="blob:"]'); if (!pasted) throw new Error('Grok 批量参考图上传失败，未检测到预览'); await tools.sleep(1000); }
      await tools.fillEditor(tabId, prompt, { selector: '.ProseMirror,[role="textbox"],[contenteditable="true"]', submit: true });

      const t0 = Date.now(), maxMs = 90000;
      let picked = [], firstReadyAt = 0, lastSig = '', stable = 0, lastCountSig = '', countStable = 0;
      while (Date.now() - t0 < maxMs) {
        if (a.signal?.aborted) throw new Error('已取消');
        await tools.sleep(1200);
        const list = await tools.runPage(tabId, `((oldImgs) => {
          const fp = s => s ? s.slice(0, 160) + '#' + s.length : '', oldSet = new Set(oldImgs || []), seen = new Set(), out = [];
          document.querySelectorAll('img').forEach((i, idx) => {
